1	//! Coordinate level geometric predicates, kept free of the node arena so the
2	//! arithmetic stays a literal transcription of `earcut.hpp`.
3	//!
4	//! Every expression below keeps the C++ operand order and association, because
5	//! floating point addition and multiplication are not associative and the
6	//! predicates are exact-comparison based (`>= 0`, `== 0`).
7	
8	/// `std::min<double>(a, b)` — returns `a` unless `b` is strictly smaller.
9	///
10	/// Not `f64::min`, which has different NaN/`-0.0` behaviour.
11	#[inline]
12	pub fn cpp_min(a: f64, b: f64) -> f64 {
13	    if b < a {
14	        b
15	    } else {
16	        a
17	    }
18	}
19	
20	/// `std::max<double>(a, b)` — returns `a` unless `b` is strictly greater.
21	#[inline]
22	pub fn cpp_max(a: f64, b: f64) -> f64 {
23	    if a < b {
24	        b
25	    } else {
26	        a
27	    }
28	}
29	
30	/// Signed area of a triangle, `(q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)`.
31	///
32	/// Negative for counter-clockwise triangles, which is the winding the algorithm
33	/// keeps the outer ring in.
34	#[inline]
35	pub fn area(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
36	    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
37	}
38	
39	/// `sign(val)` — `(0.0 < val) - (val < 0.0)`.
40	#[inline]
41	pub fn sign(val: f64) -> i32 {
42	    (0.0 < val) as i32 - (val < 0.0) as i32
43	}
44	
45	/// Whether point `p` lies inside (or on) triangle `abc`.
46	#[inline]
47	#[allow(clippy::too_many_arguments)]
48	pub fn point_in_triangle(
49	    ax: f64,
50	    ay: f64,
51	    bx: f64,
52	    by: f64,
53	    cx: f64,
54	    cy: f64,
55	    px: f64,
56	    py: f64,
57	) -> bool {
58	    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
59	        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
60	        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
61	}
62	
63	/// z-order of a point given the bounding box origin and inverse size.
64	///
65	/// Coordinates are transformed into a non-negative 15 bit integer range and
66	/// interleaved (Morton code).
67	#[inline]
68	pub fn z_order(x_: f64, y_: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
69	    // coords are transformed into non-negative 15-bit integer range
70	    let mut x: i32 = ((x_ - min_x) * inv_size) as i32;
71	    let mut y: i32 = ((y_ - min_y) * inv_size) as i32;
72	
73	    x = (x | (x << 8)) & 0x00FF00FF;
74	    x = (x | (x << 4)) & 0x0F0F0F0F;
75	    x = (x | (x << 2)) & 0x33333333;
76	    x = (x | (x << 1)) & 0x55555555;
77	
78	    y = (y | (y << 8)) & 0x00FF00FF;
79	    y = (y | (y << 4)) & 0x0F0F0F0F;
80	    y = (y | (y << 2)) & 0x33333333;
81	    y = (y | (y << 1)) & 0x55555555;
82	
83	    x | (y << 1)
84	}
