769	    /// Check if two points are equal.
770	    #[inline]
771	    fn equals(&self, p1: usize, p2: usize) -> bool {
772	        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
773	    }
