1	//! The node arena.
2	//!
3	//! `earcut.hpp` builds circular doubly linked lists out of heap allocated
4	//! `Node`s and threads raw pointers between them (`prev`/`next` for the ring,
5	//! `prevZ`/`nextZ` for the z-order curve). Raw self-referential pointers do not
6	//! translate to safe Rust, so nodes live in one arena (`Vec<Node>`) and links
7	//! are arena indices. [`NULL`] plays the role of `nullptr`.
8	//!
9	//! This is a faithful substitution: the C++ code only ever compares node
10	//! pointers for identity and never relies on their ordering or arithmetic, and
11	//! nodes are never freed individually (`removeNode` only unlinks).
12	
13	use std::ops::{Index, IndexMut};
14	
15	/// The arena equivalent of `nullptr`.
16	pub const NULL: usize = usize::MAX;
17	
18	/// A single vertex of a polygon ring, mirroring `Earcut<N>::Node`.
19	#[derive(Clone, Copy, Debug)]
20	pub struct Node {
21	    /// Vertex index in the original sequence of points (`static_cast<N>(i)`).
22	    pub i: usize,
23	    pub x: f64,
24	    pub y: f64,
25	
26	    /// Previous vertex node in a polygon ring.
27	    pub prev: usize,
28	    /// Next vertex node in a polygon ring.
29	    pub next: usize,
30	
31	    /// z-order curve value.
32	    pub z: i32,
33	
34	    /// Previous node in z-order.
35	    pub prev_z: usize,
36	    /// Next node in z-order.
37	    pub next_z: usize,
38	
39	    /// Indicates whether this is a steiner point.
40	    pub steiner: bool,
41	}
42	
43	impl Node {
44	    #[inline]
45	    pub fn new(i: usize, x: f64, y: f64) -> Node {
46	        Node {
47	            i,
48	            x,
49	            y,
50	            prev: NULL,
51	            next: NULL,
52	            z: 0,
53	            prev_z: NULL,
54	            next_z: NULL,
55	            steiner: false,
56	        }
57	    }
58	}
59	
60	/// Owns every [`Node`]; stands in for `earcut.hpp`'s `ObjectPool<Node>`.
61	pub struct NodeArena {
62	    nodes: Vec<Node>,
63	}
64	
65	impl NodeArena {
66	    #[inline]
67	    pub fn new() -> NodeArena {
68	        NodeArena { nodes: Vec::new() }
69	    }
70	
71	    /// `nodes.reset(capacity)` — drop everything and pre-reserve.
72	    #[inline]
73	    pub fn reset(&mut self, capacity: usize) {
74	        self.nodes.clear();
75	        self.nodes.reserve(capacity);
76	    }
77	
78	    /// `nodes.clear()`
79	    #[inline]
80	    pub fn clear(&mut self) {
81	        self.nodes.clear();
82	    }
83	
84	    /// `nodes.construct(i, x, y)` — allocate a node and hand back its handle.
85	    #[inline]
86	    pub fn construct(&mut self, i: usize, x: f64, y: f64) -> usize {
87	        self.nodes.push(Node::new(i, x, y));
88	        self.nodes.len() - 1
89	    }
90	
91	    #[inline]
92	    pub fn len(&self) -> usize {
93	        self.nodes.len()
94	    }
95	
96	    #[inline]
97	    pub fn is_empty(&self) -> bool {
98	        self.nodes.is_empty()
99	    }
100	}
101	
102	impl Default for NodeArena {
103	    fn default() -> NodeArena {
104	        NodeArena::new()
105	    }
106	}
107	
108	impl Index<usize> for NodeArena {
109	    type Output = Node;
110	    #[inline]
111	    fn index(&self, handle: usize) -> &Node {
112	        &self.nodes[handle]
113	    }
114	}
115	
116	impl IndexMut<usize> for NodeArena {
117	    #[inline]
118	    fn index_mut(&mut self, handle: usize) -> &mut Node {
119	        &mut self.nodes[handle]
120	    }
121	}
122

1	//! Output index types.
2	//!
3	//! Stands in for the `template <typename N = uint32_t>` parameter of
4	//! `mapbox::detail::Earcut`. The C++ code stores `static_cast<N>(i)` inside
5	//! every node, so the conversion is lossy for narrow `N`; `truncate` reproduces
6	//! that exactly.
7	
8	use std::fmt::Display;
9	
10	/// An integer type usable as a triangle index (`N` in the C++ template).
11	pub trait IndexType: Copy + Eq + Display {
12	    /// `static_cast<N>(v)`
13	    fn from_usize(v: usize) -> Self;
14	    /// Widen back to `usize`.
15	    fn to_usize(self) -> usize;
16	
17	    /// Round trip through `N`, i.e. exactly what `static_cast<N>(i)` keeps.
18	    #[inline]
19	    fn truncate(v: usize) -> usize {
20	        Self::from_usize(v).to_usize()
21	    }
22	}
23	
24	macro_rules! impl_index_type {
25	    ($($t:ty),*) => {
26	        $(
27	            impl IndexType for $t {
28	                #[inline]
29	                fn from_usize(v: usize) -> Self {
30	                    v as $t
31	                }
32	                #[inline]
33	                fn to_usize(self) -> usize {
34	                    self as usize
35	                }
36	            }
37	        )*
38	    };
39	}
40	
41	impl_index_type!(u8, u16, u32, u64, usize);
42

1	//! Point accessors.
2	//!
3	//! Stands in for `mapbox::util::nth<0, Point>::get(p)` / `nth<1, Point>::get(p)`
4	//! from the C++ library, which is how `earcut.hpp` reads coordinates out of a
5	//! user supplied point type. Implementing this trait for a custom type is the
6	//! equivalent of specializing `mapbox::util::nth`.
7	
8	/// A two dimensional point whose coordinates can be read as `f64`.
9	pub trait Point2D {
10	    /// The first coordinate (`nth<0>`).
11	    fn x(&self) -> f64;
12	    /// The second coordinate (`nth<1>`).
13	    fn y(&self) -> f64;
14	}
15	
16	impl Point2D for [f64; 2] {
17	    #[inline]
18	    fn x(&self) -> f64 {
19	        self[0]
20	    }
21	    #[inline]
22	    fn y(&self) -> f64 {
23	        self[1]
24	    }
25	}
26	
27	impl Point2D for [f32; 2] {
28	    #[inline]
29	    fn x(&self) -> f64 {
30	        self[0] as f64
31	    }
32	    #[inline]
33	    fn y(&self) -> f64 {
34	        self[1] as f64
35	    }
36	}
37	
38	impl Point2D for (f64, f64) {
39	    #[inline]
40	    fn x(&self) -> f64 {
41	        self.0
42	    }
43	    #[inline]
44	    fn y(&self) -> f64 {
45	        self.1
46	    }
47	}
48	
49	impl<'a, P: Point2D> Point2D for &'a P {
50	    #[inline]
51	    fn x(&self) -> f64 {
52	        (**self).x()
53	    }
