//! Mechanical transcription of earcut.js v2.2.4 into Rust.
//!
//! JS object references become arena indices (`usize`, `NIL` == null).
//! Everything else keeps the JS names, statement order and f64 arithmetic
//! (including operand order / association, which matters for the exact
//! comparisons the algorithm makes).
//!
//! Two modes:
//!   Mode::Js  -- exactly earcut.js v2.2.4 (hashing gate + bbox from `data`)
//!   Mode::Hpp -- earcut.hpp v2.2.4's differing bits: the `threshold`-based
//!                hashing gate, the bbox taken over the post-hole-elimination
//!                linked list, and `hashing` as a bool independent of invSize.
//! Everything else is identical between the two upstreams.

#![allow(non_snake_case, dead_code)]

pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Mode {
    Js,
    Hpp,
}

#[derive(Clone, Copy)]
struct Node {
    i: usize,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32,
    prevZ: usize,
    nextZ: usize,
    steiner: bool,
}

fn newNode(i: usize, x: f64, y: f64) -> Node {
    Node {
        i,
        x,
        y,
        prev: NIL,
        next: NIL,
        z: 0,
        prevZ: NIL,
        nextZ: NIL,
        steiner: false,
    }
}

#[derive(Default, Clone, Copy, Debug)]
pub struct Coverage {
    pub isEar_calls: u64,
    pub isEarHashed_calls: u64,
    pub pass1_entries: u64,
    pub pass2_entries: u64,
    pub pass2_splits: u64,
    pub cure_triangles: u64,
    pub split_success: u64,
    pub filterPoints_removals: u64,
    pub holes_bridged: u64,
    pub holes_dropped: u64,
}

pub struct Ec {
    n: Vec<Node>,
    triangles: Vec<u32>,
    minX: f64,
    minY: f64,
    invSize: f64,
    hashing: bool,
    mode: Mode,
    pub cov: Coverage,
}

macro_rules! g {
    ($s:expr, $i:expr) => {
        $s.n[$i]
    };
}

impl Ec {
    pub fn new(mode: Mode) -> Ec {
        Ec {
            n: Vec::new(),
            triangles: Vec::new(),
            minX: 0.0,
            minY: 0.0,
            invSize: 0.0,
            hashing: false,
            mode,
            cov: Coverage::default(),
        }
    }

    // ---- top level ---------------------------------------------------------

    /// `earcut(data, holeIndices, dim)` with dim == 2, fed from a ring list.
    pub fn earcut(&mut self, rings: &[Vec<[f64; 2]>]) -> Vec<u32> {
        self.n.clear();
        self.triangles.clear();
        self.hashing = false;
        self.invSize = 0.0;

        // flatten (this is what earcut.js callers do via flatten())
        let dim = 2usize;
        let mut data: Vec<f64> = Vec::new();
        let mut holeIndices: Vec<usize> = Vec::new();
        for (ri, r) in rings.iter().enumerate() {
            if ri > 0 {
                holeIndices.push(data.len() / dim);
            }
            for p in r {
                data.push(p[0]);
                data.push(p[1]);
            }
        }
        if rings.is_empty() {
            return Vec::new();
        }

        let hasHoles = !holeIndices.is_empty();
        let outerLen = if hasHoles {
            holeIndices[0] * dim
        } else {
            data.len()
        };
        let mut outerNode = self.linkedList(&data, 0, outerLen, dim, true);

        if outerNode == NIL || g!(self, outerNode).next == g!(self, outerNode).prev {
            return Vec::new();
        }

        if hasHoles {
            outerNode = self.eliminateHoles(&data, &holeIndices, outerNode, dim);
        }

        match self.mode {
            Mode::Js => {
                // if the shape is not too simple, we'll use z-order curve hash later
                if data.len() > 80 * dim {
                    let mut minX = data[0];
                    let mut maxX = data[0];
                    let mut minY = data[1];
                    let mut maxY = data[1];
                    let mut i = dim;
                    while i < outerLen {
                        let x = data[i];
                        let y = data[i + 1];
                        if x < minX {
                            minX = x;
                        }
                        if y < minY {
                            minY = y;
                        }
                        if x > maxX {
                            maxX = x;
                        }
                        if y > maxY {
                            maxY = y;
                        }
                        i += dim;
                    }
                    let mut invSize = if maxX - minX > maxY - minY {
                        maxX - minX
                    } else {
                        maxY - minY
                    };
                    invSize = if invSize != 0.0 { 32767.0 / invSize } else { 0.0 };
                    self.minX = minX;
                    self.minY = minY;
                    self.invSize = invSize;
                    // in JS `invSize` doubles as the "hashing" flag: 0 is falsy
                    self.hashing = invSize != 0.0;
                }
            }
            Mode::Hpp => {
                // hpp: threshold over ring sizes, bbox over the linked list
                let mut threshold: i32 = 80;
                let mut i = 0usize;
                while threshold >= 0 && i < rings.len() {
                    threshold -= rings[i].len() as i32;
                    i += 1;
                }
                self.hashing = threshold < 0;
                if self.hashing {
                    let mut p = g!(self, outerNode).next;
                    let mut minX = g!(self, outerNode).x;
                    let mut maxX = minX;
                    let mut minY = g!(self, outerNode).y;
                    let mut maxY = minY;
                    loop {
                        let x = g!(self, p).x;
                        let y = g!(self, p).y;
                        minX = if x < minX { x } else { minX };
                        minY = if y < minY { y } else { minY };
                        maxX = if maxX < x { x } else { maxX };
                        maxY = if maxY < y { y } else { maxY };
                        p = g!(self, p).next;
                        if p == outerNode {
                            break;
                        }
                    }
                    let mut invSize = if maxX - minX < maxY - minY {
                        maxY - minY
                    } else {
                        maxX - minX
                    };
                    invSize = if invSize != 0.0 { 32767.0 / invSize } else { 0.0 };
                    self.minX = minX;
                    self.minY = minY;
                    self.invSize = invSize;
                }
            }
        }

        self.earcutLinked(outerNode, dim, 0);

        std::mem::take(&mut self.triangles)
    }

    // ---- linkedList / signedArea -------------------------------------------

    fn signedArea(&self, data: &[f64], start: usize, end: usize, dim: usize) -> f64 {
        let mut sum = 0.0f64;
        let mut i = start;
        let mut j = end - dim;
        while i < end {
            sum += (data[j] - data[i]) * (data[i + 1] + data[j + 1]);
            j = i;
            i += dim;
        }
        sum
    }

    fn linkedList(
        &mut self,
        data: &[f64],
        start: usize,
        end: usize,
        dim: usize,
        clockwise: bool,
    ) -> usize {
        let mut last = NIL;
        if end <= start {
            return NIL; // js would blow up here; hpp returns null
        }

        if clockwise == (self.signedArea(data, start, end, dim) > 0.0) {
            let mut i = start;
            while i < end {
                last = self.insertNode(i, data[i], data[i + 1], last);
                i += dim;
            }
        } else {
            let mut i = end - dim;
            loop {
                last = self.insertNode(i, data[i], data[i + 1], last);
                if i < start + dim {
                    break;
                }
                i -= dim;
            }
        }

        if last != NIL {
            let ln = g!(self, last).next;
            if self.equals(last, ln) {
                self.removeNode(last);
                last = g!(self, last).next;
            }
        }

        last
    }

    // ---- filterPoints ------------------------------------------------------

    fn filterPoints(&mut self, start: usize, end_in: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end_in == NIL { start } else { end_in };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let pn = g!(self, p).next;
            let pp = g!(self, p).prev;
            if !g!(self, p).steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.removeNode(p);
                self.cov.filterPoints_removals += 1;
                p = g!(self, p).prev;
                end = p;
                if p == g!(self, p).next {
                    break;
                }
                again = true;
            } else {
                p = g!(self, p).next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    // ---- earcutLinked ------------------------------------------------------

    fn earcutLinked(&mut self, ear_in: usize, dim: usize, pass: i32) {
        let mut ear = ear_in;
        if ear == NIL {
            return;
        }

        if pass == 0 && self.hashing {
            self.indexCurve(ear);
        }

        let mut stop = ear;

        while g!(self, ear).prev != g!(self, ear).next {
            let prev = g!(self, ear).prev;
            let next = g!(self, ear).next;

            let ok = if self.hashing {
                self.cov.isEarHashed_calls += 1;
                self.isEarHashed(ear)
            } else {
                self.cov.isEar_calls += 1;
                self.isEar(ear)
            };

            if ok {
                self.triangles.push((g!(self, prev).i / dim) as u32);
                self.triangles.push((g!(self, ear).i / dim) as u32);
                self.triangles.push((g!(self, next).i / dim) as u32);

                self.removeNode(ear);

                ear = g!(self, next).next;
                stop = g!(self, next).next;
                continue;
            }

            ear = next;

            if ear == stop {
                if pass == 0 {
                    self.cov.pass1_entries += 1;
                    let f = self.filterPoints(ear, NIL);
                    self.earcutLinked(f, dim, 1);
                } else if pass == 1 {
                    self.cov.pass2_entries += 1;
                    let f = self.filterPoints(ear, NIL);
                    ear = self.cureLocalIntersections(f, dim);
                    self.earcutLinked(ear, dim, 2);
                } else if pass == 2 {
                    self.cov.pass2_splits += 1;
                    self.splitEarcut(ear, dim);
                }
                break;
            }
        }
    }

    // ---- isEar / isEarHashed ----------------------------------------------

    fn isEar(&self, ear: usize) -> bool {
        let a = g!(self, ear).prev;
        let b = ear;
        let c = g!(self, ear).next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let (ax, ay) = (g!(self, a).x, g!(self, a).y);
        let (bx, by) = (g!(self, b).x, g!(self, b).y);
        let (cx, cy) = (g!(self, c).x, g!(self, c).y);

        let mut p = g!(self, c).next;
        while p != a {
            if pointInTriangle(ax, ay, bx, by, cx, cy, g!(self, p).x, g!(self, p).y) {
                let pp = g!(self, p).prev;
                let pn = g!(self, p).next;
                if self.area(pp, p, pn) >= 0.0 {
                    return false;
                }
            }
            p = g!(self, p).next;
        }
        true
    }

    fn isEarHashed(&self, ear: usize) -> bool {
        let a = g!(self, ear).prev;
        let b = ear;
        let c = g!(self, ear).next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let (ax, bx, cx) = (g!(self, a).x, g!(self, b).x, g!(self, c).x);
        let (ay, by, cy) = (g!(self, a).y, g!(self, b).y, g!(self, c).y);

        // triangle bbox
        let x0 = if ax < bx {
            if ax < cx {
                ax
            } else {
                cx
            }
        } else if bx < cx {
            bx
        } else {
            cx
        };
        let y0 = if ay < by {
            if ay < cy {
                ay
            } else {
                cy
            }
        } else if by < cy {
            by
        } else {
            cy
        };
        let x1 = if ax > bx {
            if ax > cx {
                ax
            } else {
                cx
            }
        } else if bx > cx {
            bx
        } else {
            cx
        };
        let y1 = if ay > by {
            if ay > cy {
                ay
            } else {
                cy
            }
        } else if by > cy {
            by
        } else {
            cy
        };

        let minZ = self.zOrder(x0, y0);
        let maxZ = self.zOrder(x1, y1);

        let mut p = g!(self, ear).prevZ;
        let mut nn = g!(self, ear).nextZ;

        // look for points inside the triangle in both directions
        while p != NIL && g!(self, p).z >= minZ && nn != NIL && g!(self, nn).z <= maxZ {
            if g!(self, p).x >= x0
                && g!(self, p).x <= x1
                && g!(self, p).y >= y0
                && g!(self, p).y <= y1
                && p != a
                && p != c
                && pointInTriangle(ax, ay, bx, by, cx, cy, g!(self, p).x, g!(self, p).y)
                && self.area(g!(self, p).prev, p, g!(self, p).next) >= 0.0
            {
                return false;
            }
            p = g!(self, p).prevZ;

            if g!(self, nn).x >= x0
                && g!(self, nn).x <= x1
                && g!(self, nn).y >= y0
                && g!(self, nn).y <= y1
                && nn != a
                && nn != c
                && pointInTriangle(ax, ay, bx, by, cx, cy, g!(self, nn).x, g!(self, nn).y)
                && self.area(g!(self, nn).prev, nn, g!(self, nn).next) >= 0.0
            {
                return false;
            }
            nn = g!(self, nn).nextZ;
        }

        // remaining points in decreasing z-order
        while p != NIL && g!(self, p).z >= minZ {
            if g!(self, p).x >= x0
                && g!(self, p).x <= x1
                && g!(self, p).y >= y0
                && g!(self, p).y <= y1
                && p != a
                && p != c
                && pointInTriangle(ax, ay, bx, by, cx, cy, g!(self, p).x, g!(self, p).y)
                && self.area(g!(self, p).prev, p, g!(self, p).next) >= 0.0
            {
                return false;
            }
            p = g!(self, p).prevZ;
        }

        // remaining points in increasing z-order
        while nn != NIL && g!(self, nn).z <= maxZ {
            if g!(self, nn).x >= x0
                && g!(self, nn).x <= x1
                && g!(self, nn).y >= y0
                && g!(self, nn).y <= y1
                && nn != a
                && nn != c
                && pointInTriangle(ax, ay, bx, by, cx, cy, g!(self, nn).x, g!(self, nn).y)
                && self.area(g!(self, nn).prev, nn, g!(self, nn).next) >= 0.0
            {
                return false;
            }
            nn = g!(self, nn).nextZ;
        }

        true
    }

    // ---- cureLocalIntersections -------------------------------------------

    fn cureLocalIntersections(&mut self, start_in: usize, dim: usize) -> usize {
        let mut start = start_in;
        if start == NIL {
            return NIL;
        }
        let mut p = start;
        loop {
            let a = g!(self, p).prev;
            let pn = g!(self, p).next;
            let b = g!(self, pn).next;

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locallyInside(a, b)
                && self.locallyInside(b, a)
            {
                self.triangles.push((g!(self, a).i / dim) as u32);
                self.triangles.push((g!(self, p).i / dim) as u32);
                self.triangles.push((g!(self, b).i / dim) as u32);
                self.cov.cure_triangles += 1;

                self.removeNode(p);
                let pnext = g!(self, p).next;
                self.removeNode(pnext);

                p = b;
                start = b;
            }

            p = g!(self, p).next;
            if p == start {
                break;
            }
        }

        self.filterPoints(p, NIL)
    }

    // ---- splitEarcut -------------------------------------------------------

    fn splitEarcut(&mut self, start: usize, dim: usize) {
        let mut a = start;
        loop {
            let an0 = g!(self, a).next;
            let mut b = g!(self, an0).next;
            while b != g!(self, a).prev {
                if g!(self, a).i != g!(self, b).i && self.isValidDiagonal(a, b) {
                    let mut c = self.splitPolygon(a, b);
                    self.cov.split_success += 1;

                    let an = g!(self, a).next;
                    a = self.filterPoints(a, an);
                    let cn = g!(self, c).next;
                    c = self.filterPoints(c, cn);

                    self.earcutLinked(a, dim, 0);
                    self.earcutLinked(c, dim, 0);
                    return;
                }
                b = g!(self, b).next;
            }
            a = g!(self, a).next;
            if a == start {
                break;
            }
        }
    }

    // ---- holes -------------------------------------------------------------

    fn eliminateHoles(
        &mut self,
        data: &[f64],
        holeIndices: &[usize],
        outerNode_in: usize,
        dim: usize,
    ) -> usize {
        let mut outerNode = outerNode_in;
        let mut queue: Vec<usize> = Vec::new();
        let len = holeIndices.len();
        for i in 0..len {
            let start = holeIndices[i] * dim;
            let end = if i < len - 1 {
                holeIndices[i + 1] * dim
            } else {
                data.len()
            };
            let list = self.linkedList(data, start, end, dim, false);
            if list != NIL {
                if list == g!(self, list).next {
                    self.n[list].steiner = true;
                }
                let lm = self.getLeftmost(list);
                queue.push(lm);
            }
        }

        // queue.sort(compareX) -- Array.prototype.sort is stable in ES2019+
        let xs: Vec<f64> = queue.iter().map(|&q| self.n[q].x).collect();
        let mut idx: Vec<usize> = (0..queue.len()).collect();
        idx.sort_by(|&l, &r| xs[l].partial_cmp(&xs[r]).unwrap_or(std::cmp::Ordering::Equal));
        let queue: Vec<usize> = idx.into_iter().map(|k| queue[k]).collect();

        for &q in queue.iter() {
            let before = outerNode;
            outerNode = self.eliminateHole(q, outerNode);
            if outerNode == before {
                // could be a no-bridge drop; counted inside eliminateHole
            }
        }

        outerNode
    }

    fn eliminateHole(&mut self, hole: usize, outerNode: usize) -> usize {
        let bridge = self.findHoleBridge(hole, outerNode);
        if bridge == NIL {
            self.cov.holes_dropped += 1;
            return outerNode;
        }
        self.cov.holes_bridged += 1;

        let bridgeReverse = self.splitPolygon(bridge, hole);

        let brn = g!(self, bridgeReverse).next;
        self.filterPoints(bridgeReverse, brn);
        let bn = g!(self, bridge).next;
        self.filterPoints(bridge, bn)
    }

    fn findHoleBridge(&self, hole: usize, outerNode: usize) -> usize {
        let mut p = outerNode;
        let hx = g!(self, hole).x;
        let hy = g!(self, hole).y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        loop {
            let pn = g!(self, p).next;
            if hy <= g!(self, p).y && hy >= g!(self, pn).y && g!(self, pn).y != g!(self, p).y {
                // JS: var x = p.x + (hy - p.y) * (p.next.x - p.x) / (p.next.y - p.y);
                let x = g!(self, p).x
                    + (hy - g!(self, p).y) * (g!(self, pn).x - g!(self, p).x)
                        / (g!(self, pn).y - g!(self, p).y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if g!(self, p).x < g!(self, pn).x { p } else { pn };
                    if x == hx {
                        return m;
                    }
                }
            }
            p = g!(self, p).next;
            if p == outerNode {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        let stop = m;
        let mut tanMin = f64::INFINITY;
        p = m;
        let mut mx = g!(self, m).x;
        let mut my = g!(self, m).y;

        loop {
            let px = g!(self, p).x;
            let py = g!(self, p).y;
            if hx >= px
                && px >= mx
                && hx != px
                && pointInTriangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px);

                if self.locallyInside(p, hole)
                    && (tan < tanMin
                        || (tan == tanMin
                            && (px > g!(self, m).x || self.sectorContainsSector(m, p))))
                {
                    m = p;
                    mx = g!(self, m).x;
                    my = g!(self, m).y;
                    tanMin = tan;
                }
            }
            p = g!(self, p).next;
            if p == stop {
                break;
            }
        }

        m
    }

    fn sectorContainsSector(&self, m: usize, p: usize) -> bool {
        self.area(g!(self, m).prev, m, g!(self, p).prev) < 0.0
            && self.area(g!(self, p).next, m, g!(self, m).next) < 0.0
    }

    // ---- z-order -----------------------------------------------------------

    fn indexCurve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if g!(self, p).z == 0 {
                let (x, y) = (g!(self, p).x, g!(self, p).y);
                self.n[p].z = self.zOrder(x, y);
            }
            let pp = g!(self, p).prev;
            let pn = g!(self, p).next;
            self.n[p].prevZ = pp;
            self.n[p].nextZ = pn;
            p = g!(self, p).next;
            if p == start {
                break;
            }
        }

        let pz = g!(self, p).prevZ;
        self.n[pz].nextZ = NIL;
        self.n[p].prevZ = NIL;

        self.sortLinked(p);
    }

    fn sortLinked(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut inSize: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut numMerges = 0;

            while p != NIL {
                numMerges += 1;
                let mut q = p;
                let mut pSize = 0;
                let mut i = 0;
                while i < inSize {
                    pSize += 1;
                    q = g!(self, q).nextZ;
                    if q == NIL {
                        break;
                    }
                    i += 1;
                }
                let mut qSize = inSize;

                while pSize > 0 || (qSize > 0 && q != NIL) {
                    let e;
                    if pSize == 0 {
                        e = q;
                        q = g!(self, q).nextZ;
                        qSize -= 1;
                    } else if qSize == 0 || q == NIL {
                        e = p;
                        p = g!(self, p).nextZ;
                        pSize -= 1;
                    } else if g!(self, p).z <= g!(self, q).z {
                        e = p;
                        p = g!(self, p).nextZ;
                        pSize -= 1;
                    } else {
                        e = q;
                        q = g!(self, q).nextZ;
                        qSize -= 1;
                    }

                    if tail != NIL {
                        self.n[tail].nextZ = e;
                    } else {
                        list = e;
                    }
                    self.n[e].prevZ = tail;
                    tail = e;
                }
                p = q;
            }

            self.n[tail].nextZ = NIL;

            if numMerges <= 1 {
                return list;
            }
            inSize *= 2;
        }
    }

    fn zOrder(&self, x_: f64, y_: f64) -> i32 {
        let mut x = ((x_ - self.minX) * self.invSize) as i32;
        let mut y = ((y_ - self.minY) * self.invSize) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    // ---- helpers -----------------------------------------------------------

    fn getLeftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if g!(self, p).x < g!(self, leftmost).x
                || (g!(self, p).x == g!(self, leftmost).x && g!(self, p).y < g!(self, leftmost).y)
            {
                leftmost = p;
            }
            p = g!(self, p).next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    fn isValidDiagonal(&self, a: usize, b: usize) -> bool {
        let an = g!(self, a).next;
        let ap = g!(self, a).prev;
        let bp = g!(self, b).prev;
        let bn = g!(self, b).next;

        g!(self, an).i != g!(self, b).i
            && g!(self, ap).i != g!(self, b).i
            && !self.intersectsPolygon(a, b)
            && ((self.locallyInside(a, b)
                && self.locallyInside(b, a)
                && self.middleInside(a, b)
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    #[inline]
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (g!(self, q).y - g!(self, p).y) * (g!(self, r).x - g!(self, q).x)
            - (g!(self, q).x - g!(self, p).x) * (g!(self, r).y - g!(self, q).y)
    }

    #[inline]
    fn equals(&self, p1: usize, p2: usize) -> bool {
        g!(self, p1).x == g!(self, p2).x && g!(self, p1).y == g!(self, p2).y
    }

    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true;
        }
        if o1 == 0 && self.onSegment(p1, p2, q1) {
            return true;
        }
        if o2 == 0 && self.onSegment(p1, q2, q1) {
            return true;
        }
        if o3 == 0 && self.onSegment(p2, p1, q2) {
            return true;
        }
        if o4 == 0 && self.onSegment(p2, q1, q2) {
            return true;
        }
        false
    }

    fn onSegment(&self, p: usize, q: usize, r: usize) -> bool {
        let (px, py) = (g!(self, p).x, g!(self, p).y);
        let (qx, qy) = (g!(self, q).x, g!(self, q).y);
        let (rx, ry) = (g!(self, r).x, g!(self, r).y);
        qx <= (if px < rx { rx } else { px })
            && qx >= (if rx < px { rx } else { px })
            && qy <= (if py < ry { ry } else { py })
            && qy >= (if ry < py { ry } else { py })
    }

    fn intersectsPolygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = g!(self, p).next;
            if g!(self, p).i != g!(self, a).i
                && g!(self, pn).i != g!(self, a).i
                && g!(self, p).i != g!(self, b).i
                && g!(self, pn).i != g!(self, b).i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = g!(self, p).next;
            if p == a {
                break;
            }
        }
        false
    }

    fn locallyInside(&self, a: usize, b: usize) -> bool {
        let ap = g!(self, a).prev;
        let an = g!(self, a).next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    fn middleInside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (g!(self, a).x + g!(self, b).x) / 2.0;
        let py = (g!(self, a).y + g!(self, b).y) / 2.0;
        loop {
            let pn = g!(self, p).next;
            let (pyy, nyy) = (g!(self, p).y, g!(self, pn).y);
            if ((pyy > py) != (nyy > py))
                && nyy != pyy
                && (px < (g!(self, pn).x - g!(self, p).x) * (py - pyy) / (nyy - pyy)
                    + g!(self, p).x)
            {
                inside = !inside;
            }
            p = g!(self, p).next;
            if p == a {
                break;
            }
        }
        inside
    }

    fn splitPolygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.push(newNode(g!(self, a).i, g!(self, a).x, g!(self, a).y));
        let b2 = self.push(newNode(g!(self, b).i, g!(self, b).x, g!(self, b).y));
        let an = g!(self, a).next;
        let bp = g!(self, b).prev;

        self.n[a].next = b;
        self.n[b].prev = a;

        self.n[a2].next = an;
        self.n[an].prev = a2;

        self.n[b2].next = a2;
        self.n[a2].prev = b2;

        self.n[bp].next = b2;
        self.n[b2].prev = bp;

        b2
    }

    fn insertNode(&mut self, i: usize, x: f64, y: f64, last: usize) -> usize {
        let p = self.push(newNode(i, x, y));
        if last == NIL {
            self.n[p].prev = p;
            self.n[p].next = p;
        } else {
            let ln = g!(self, last).next;
            self.n[p].next = ln;
            self.n[p].prev = last;
            self.n[ln].prev = p;
            self.n[last].next = p;
        }
        p
    }

    fn removeNode(&mut self, p: usize) {
        let pn = g!(self, p).next;
        let pp = g!(self, p).prev;
        self.n[pn].prev = pp;
        self.n[pp].next = pn;

        let pz = g!(self, p).prevZ;
        let nz = g!(self, p).nextZ;
        if pz != NIL {
            self.n[pz].nextZ = nz;
        }
        if nz != NIL {
            self.n[nz].prevZ = pz;
        }
    }

    #[inline]
    fn push(&mut self, nd: Node) -> usize {
        self.n.push(nd);
        self.n.len() - 1
    }
}

#[inline]
pub fn sign(v: f64) -> i32 {
    (0.0 < v) as i32 - (v < 0.0) as i32
}

#[inline]
#[allow(clippy::too_many_arguments)]
pub fn pointInTriangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}
